from pypdf import PdfReader

reader = PdfReader("/root/sc100-blank.pdf")
fields = reader.get_fields()
if fields:
    for field_name, field_data in fields.items():
        print(f"{field_name}: {field_data.get('/FT', 'Unknown')}")
else:
    print("No fields found.")

from pypdf import PdfReader

reader = PdfReader("/root/sc100-blank.pdf")
fields = reader.get_fields()

for name, field in fields.items():
    if field.get('/FT') == '/Btn':
        # It's a button (checkbox or radio)
        # Check /AP /N for possible values
        if '/AP' in field and '/N' in field['/AP']:
            vals = list(field['/AP']['/N'].keys())
            print(f"Checkbox {name}: {vals}")
        else:
            print(f"Checkbox {name}: No AP/N found")
    elif field.get('/FT') == '/Tx':
        print(f"Text {name}")

